import{c as r,$ as o,Q as a,j as s,g as e,o as n,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const g="/img/ru/front/warehouse.webp",q=JSON.parse('{"title":"Материалы и склад","description":"Универсальный складской учет, партионные закупки, метод МАК, логистика и печать этикеток со штрихкодами в ОмниКрафт ЕРП.","frontmatter":{"title":"Материалы и склад","description":"Универсальный складской учет, партионные закупки, метод МАК, логистика и печать этикеток со штрихкодами в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-19","order":2},"headers":[],"relativePath":"ru/docs/resources/warehouse.md","filePath":"ru/docs/resources/warehouse.md","lastUpdated":1795046400000}'),h={name:"ru/docs/resources/warehouse.md"},c={id:"материалы-и-склад",tabindex:"-1"};function p(u,t,m,f,x,b){const l=o("DocIcon");return a(),s("div",null,[e("h1",c,[n(l,{name:"warehouse"}),t[0]||(t[0]=i(" Материалы и склад ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#материалы-и-склад","aria-label":'Permalink to "Материалы и склад"'},"​",-1))]),t[2]||(t[2]=d('<figure class="doc-image craft-window-frame" data-title="Материалы и склад — ОмниКрафт ЕРП"><img src="'+g+'" alt="Главное окно вкладки «Склад»"><figcaption>Главное окно вкладки «Склад»</figcaption></figure><p>Вкладка <strong>«Склад»</strong> — это центральный узел материального обеспечения любого дела. Будь то сырье для производственного цеха, запасные части и расходники сервисного центра или партии готовых товаров для розницы и маркетплейсов — физические запасы на полках представляют собой замороженные деньги бизнеса.</p><p>В <strong>ОмниКрафт ЕРП</strong> складской контур не просто считает остатки в штуках, метрах или килограммах. Он неразрывно связан с финансовым учетом: вычисляет реальную себестоимость запасов по профессиональному методу <strong>скользящей средней стоимости (МАК)</strong>, честно распределяет расходы на транспортную доставку и автоматически формирует расходные ордера в кассе движения денег (ДДС).</p><hr><h2 id="физика-себестоимости-скользящая-средняя-стоимость-мак" tabindex="-1">Физика себестоимости: Скользящая средняя стоимость (МАК) <a class="header-anchor" href="#физика-себестоимости-скользящая-средняя-стоимость-мак" aria-label="Permalink to &quot;Физика себестоимости: Скользящая средняя стоимость (МАК)&quot;">​</a></h2><p>Цены поставщиков постоянно меняются из-за инфляции, сезонности или смены партий. Если считать себестоимость по последней цене закупки, вы завысите стоимость старых остатков; если считать по старой цене — начнете торговать в скрытый убыток.</p><p>ОмниКрафт ЕРП использует промышленный стандарт — <strong>скользящую среднюю стоимость (метод МАК)</strong>:</p><div class="craft-metaphor-card"><div class="metaphor-badge">Эффект «банки с краской»</div><p class="metaphor-lead">При смешивании двух партий одной краски по разной цене себестоимость литра становится средневзвешенной.</p><table class="craft-matrix-table" style="margin-top:1rem;"><thead><tr><th style="width:35%;">Партия сырья</th><th style="width:20%;">Объём</th><th style="width:25%;">Закупочная цена</th><th style="width:20%;">Сумма, ₽</th></tr></thead><tbody><tr><td><strong>Остаток на складе</strong></td><td>10 кг</td><td>500 ₽/кг</td><td>5 000 ₽</td></tr><tr><td><strong>Новая закупка</strong></td><td>10 кг</td><td>700 ₽/кг</td><td>7 000 ₽</td></tr><tr><td><strong>Итого в остатке (МАК)</strong></td><td><strong>20 кг</strong></td><td><strong>600 ₽/кг</strong></td><td><strong>12 000 ₽</strong></td></tr></tbody></table></div><p>При каждом списании материала на изделие или в заказ-наряд программа списывает сырье именно по текущей средней цене. Вам не нужно помнить, из какой конкретно партии взята упаковка — система защищает вашу маржу автоматически.</p><div class="tip custom-block"><p class="custom-block-title">Доставка увеличивает себестоимость единицы</p><p>Стоимость доставки сырья от поставщика — это не отдельная абстрактная трата, а прямая часть закупочной стоимости материала. В ОмниКрафт ЕРП транспортные расходы автоматически зашиваются в учетную цену каждой единицы остатка.</p></div><hr><h2 id="отраслевая-специфика-складов" tabindex="-1">Отраслевая специфика складов <a class="header-anchor" href="#отраслевая-специфика-складов" aria-label="Permalink to &quot;Отраслевая специфика складов&quot;">​</a></h2><p>В зависимости от выбранного профиля деятельности назначение складских запасов адаптируется под ваши задачи:</p><h3 id="production" tabindex="-1">В производстве <a class="header-anchor" href="#production" aria-label="Permalink to &quot;В производстве {#production}&quot;">​</a></h3><p>Склад хранит исходные материалы, которые физически трансформируются в готовые изделия:</p><ul><li><strong>Типовая номенклатура:</strong> листовой металл, древесина, натуральная кожа, ткани, глина, пластик для 3D-печати, нитки, фурнитура, клей, лаки и транспортировочные коробки.</li><li><strong>Интеграция с расчетами:</strong> нормы расхода из модуля «Калькулятор» привязаны к складским карточкам. При запуске партии изделий на верстаке программа автоматически бронирует сырье на складе, а по завершении сборки списывает его в точных долях миллиметров, граммов или квадратных дециметров.</li></ul><h3 id="services" tabindex="-1">В сфере услуг <a class="header-anchor" href="#services" aria-label="Permalink to &quot;В сфере услуг {#services}&quot;">​</a></h3><p>Склад выступает фондом запасных частей, ремкомплектов и монтажных расходников:</p><ul><li><strong>Типовая номенклатура:</strong> экраны, шлейфы, чипы, фильтры, тормозные колодки, ремни, трубы, фитинги, припой, крепежные наборы, техническая химия и стерильные комплекты.</li><li><strong>Интеграция с заказами:</strong> запчасти и материалы добавляются прямо в бланк заказ-наряда клиента. Программа списывает их со склада в момент закрытия наряда, перенося стоимость деталей в итоговый чек и кассу ДДС.</li></ul><h3 id="trade" tabindex="-1">В торговле и у селлеров маркетплейсов <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;В торговле и у селлеров маркетплейсов {#trade}&quot;">​</a></h3><p>Склад обеспечивает оперативное товародвижение готовой продукции:</p><ul><li><strong>Типовая номенклатура:</strong> штучный упакованный товар от фабрик, брендированная упаковка, полиэтиленовые курьерские пакеты, скотч, наполнитель и термоэтикетки.</li><li><strong>Контроль дефицита:</strong> своевременный дозаказ ходовых артикулов предотвращает обнуление товарных карточек на маркетплейсах (состояние out-of-stock), сохраняя позиции магазина в поисковой выдаче.</li></ul><hr><h2 id="паспорт-материала-и-умные-карточки" tabindex="-1">Паспорт материала и умные карточки <a class="header-anchor" href="#паспорт-материала-и-умные-карточки" aria-label="Permalink to &quot;Паспорт материала и умные карточки&quot;">​</a></h2><p>Добавление новой позиции в базу осуществляется нажатием кнопки <strong>«+» (Новая позиция)</strong> в верхней панели. Карточка материала содержит параметры для точного ведения учета:</p><ul><li><strong>Наименование:</strong> понятное рабочее название (например, <em>«Профиль алюминиевый конструкционный 20×20 мм»</em> или <em>«Дисплейный модуль OLED в сборе»</em>).</li><li><strong>Артикул:</strong> уникальный внутренний код. Если оставить поле пустым, программа автоматически присвоит сквозной артикул формата <code>АРТ-0001</code>, исключающий дублирование при поиске и сканировании.</li><li><strong>Категория:</strong> смысловая группа (например, <em>«Металл»</em>, <em>«Фурнитура»</em>, <em>«Электроника»</em>, <em>«Упаковка»</em>). Список категорий настраивается прямо из окна карточки.</li><li><strong>Единица измерения:</strong> физическая величина, в которой рассчитывается расход (пог. м, кв. дм, шт., кг, л, мл). Рекомендуется выбирать ту единицу, в которой материал расходуется в реальной работе.</li><li><strong>Порог безопасности (Мин. остаток):</strong> неснижаемый запас, при падении ниже которого строка подсвечивается предупреждающим цветом: <ul><li><em>Ручной ввод:</em> жестко заданное минимальное число (например, не менее 5 штук).</li><li><em>Адаптивный авторасчет:</em> если указать <code>0</code>, программа автоматически анализирует частоту и объем последних 20 закупок и выставляет динамический буфер в 20%.</li></ul></li></ul><h3 id="мульти-поставщики-и-веб-ссылки" tabindex="-1">Мульти-поставщики и веб-ссылки <a class="header-anchor" href="#мульти-поставщики-и-веб-ссылки" aria-label="Permalink to &quot;Мульти-поставщики и веб-ссылки&quot;">​</a></h3><p>К каждому материалу можно привязать несколько ссылок на различных поставщиков (например, крупный оптовый склад и розничный магазин быстрой подсортировки):</p><ul><li><strong>«Сделать главным» (булавка):</strong> выбранная ссылка открыто отображается прямо в ячейке таблицы склада. Клик по ней мгновенно открывает страницу закупки в браузере.</li><li><strong>«Показывать в таблице»:</strong> альтернативные поставщики аккуратно сворачиваются в компактный бейдж <code>(+N)</code>, не перегружая рабочую область.</li></ul><hr><h2 id="адресное-хранение-материалов" tabindex="-1">Адресное хранение материалов <a class="header-anchor" href="#адресное-хранение-материалов" aria-label="Permalink to &quot;Адресное хранение материалов&quot;">​</a></h2><p>В растущей мастерской или сервисном центре поиск нужной позиции отнимает драгоценное рабочее время, если сырье и комплектующие разложены хаотично. В ОмниКрафт ЕРП встроен справочник физических локаций, позволяющий организовать прозрачное адресное хранение на складе.</p><h3 id="цеховая-задача-и-иерархия-хранения" tabindex="-1">Цеховая задача и иерархия хранения <a class="header-anchor" href="#цеховая-задача-и-иерархия-хранения" aria-label="Permalink to &quot;Цеховая задача и иерархия хранения&quot;">​</a></h3><p>Адресное хранение связывает виртуальный учет материалов с физической топологией мастерской:</p><ol><li><strong>Точная навигация по цеху:</strong> мастер или помощник сразу видит в карточке и таблице склада, на каком стеллаже, полке или в каком выдвижном ящике находится позиция (например, <em>«Стеллаж А, Полка 2, Ячейка 04»</em>).</li><li><strong>Безошибочная сборка партий:</strong> при передаче задания на верстак или комплектации заказ-наряда адреса ячеек исключают путаницу между похожими рулонами кожи, марками сплавов или номиналами радиодеталей.</li><li><strong>Ускоренная инвентаризация:</strong> сверка фактических остатков проводится последовательно стеллаж за стеллажем без необходимости останавливать работу всего цеха.</li></ol><h3 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h3><p>Для организации адресного хранения подготовьте структуру маркировки цеха: обозначьте стеллажи буквами, полки номерами, а ячейки или органайзеры — двузначными кодами.</p><h3 id="пошаговыи-порядок-настроики-локации-и-привязки-к-сырью" tabindex="-1">Пошаговый порядок настройки локаций и привязки к сырью <a class="header-anchor" href="#пошаговыи-порядок-настроики-локации-и-привязки-к-сырью" aria-label="Permalink to &quot;Пошаговый порядок настройки локаций и привязки к сырью&quot;">​</a></h3><ol><li><strong>Вызов диалога управления локациями:</strong><ul><li>При создании новой позиции кнопкой <strong>«+» (Новая позиция)</strong> или редактировании существующей карточки нажмите кнопку с иконкой карандаша рядом с полем <strong>«Локация / Стеллаж»</strong>;</li><li>На экране откроется модальное окно <strong>«Управление локациями»</strong>.</li></ul></li><li><strong>Добавление физического места хранения:</strong><ul><li>В поле ввода введите название локации (например, <em>«Стеллаж 1 / Полка В»</em>, <em>«Шкаф химикатов, отсек 3»</em>);</li><li>Нажмите кнопку <strong>«Добавить»</strong>. Локация моментально зафиксируется в общем реестре доступных мест.</li></ul></li><li><strong>Редактирование и переименование зон:</strong><ul><li>Если стеллаж перемещен или перемаркирован, нажмите кнопку с иконкой карандаша напротив названия локации в списке;</li><li>В окне редактирования скорректируйте наименование в поле <strong>«Название»</strong> и нажмите кнопку <strong>«Сохранить»</strong>;</li><li>Все привязанные к этой локации материалы автоматически получат обновленный адрес без ручной перепривязки каждого артикула.</li></ul></li><li><strong>Удаление освободившихся локаций:</strong><ul><li>Если стеллаж демонтирован, нажмите кнопку с иконкой корзины напротив локации;</li><li>Программа безопасно удалит локацию из списка быстрого выбора.</li></ul></li><li><strong>Выбор локации и отображение в таблице остатков:</strong><ul><li>Нажмите кнопку <strong>«Закрыть»</strong> в окне управления;</li><li>В карточке материала выберите созданное место хранения в выпадающем списке;</li><li>Нажмите кнопку <strong>«Сохранить»</strong>. Название локации отобразится в основной таблице склада в колонке адреса, ускоряя фильтрацию и поиск сырья при комплектации партий.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Печать бирок с адресным кодом</p><p>При формировании складских наклеек через инструмент «Пакетная печать бирок» программа может наносить адрес хранения крупным текстом под линейным штрихкодом Code128. Это позволяет маркировать как коробки с сырьем, так и сами физические ячейки стеллажей для мгновенной сверки ручным сканером.</p></div><hr><h2 id="партионная-закупка-и-автоматическая-логистика" tabindex="-1">Партионная закупка и автоматическая логистика <a class="header-anchor" href="#партионная-закупка-и-автоматическая-логистика" aria-label="Permalink to &quot;Партионная закупка и автоматическая логистика&quot;">​</a></h2><p>Главная финансовая операция склада — кнопка <strong>«Партионная закупка»</strong> (значок тележки в панели инструментов).</p><div class="warning custom-block"><p class="custom-block-title">Не путайте закупку с инвентаризацией</p><p>Никогда не приходуйте купленные материалы через кнопку инвентаризации. Инвентаризация меняет лишь количество на полке, не учитывая цену закупки и не фиксируя расход в кассе. Все плановые поставки оформляются строго через «Партионную закупку».</p></div><h3 id="справедливое-распределение-расходов-на-доставку" tabindex="-1">Справедливое распределение расходов на доставку <a class="header-anchor" href="#справедливое-распределение-расходов-на-доставку" aria-label="Permalink to &quot;Справедливое распределение расходов на доставку&quot;">​</a></h3><p>Когда поставщик отправляет сборный груз, транспортная компания выставляет единый счет за перевозку. Простое деление доставки поровну искажает экономику: дешевые расходники необоснованно взлетают в цене, а дорогие материалы оказываются недооцененными.</p><p>В ОмниКрафт ЕРП действует закон <strong>пропорционального распределения доставки по стоимости позиций</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Позиция в закупке</th><th style="text-align:left;">Стоимость партии</th><th style="text-align:left;">Доля в чеке</th><th style="text-align:left;">Распределение доставки (всего 1 000 ₽)</th><th style="text-align:left;">Итоговая себестоимость партии</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Дорогой материал</strong> <em>(напр. двигатель или кожа)</em></td><td style="text-align:left;">9 000 ₽</td><td style="text-align:left;"><code>90%</code></td><td style="text-align:left;"><strong>+ 900 ₽</strong></td><td style="text-align:left;"><strong>9 900 ₽</strong></td></tr><tr><td style="text-align:left;"><strong>Дешевый расходник</strong> <em>(напр. болты или скотч)</em></td><td style="text-align:left;">1 000 ₽</td><td style="text-align:left;"><code>10%</code></td><td style="text-align:left;"><strong>+ 100 ₽</strong></td><td style="text-align:left;"><strong>1 100 ₽</strong></td></tr><tr><td style="text-align:left;"><strong>ИТОГО:</strong></td><td style="text-align:left;"><strong>10 000 ₽</strong></td><td style="text-align:left;"><code>100%</code></td><td style="text-align:left;"><strong>1 000 ₽</strong></td><td style="text-align:left;"><strong>11 000 ₽</strong></td></tr></tbody></table><p>При проведении закупки программа за доли секунды:</p><ol><li>Приходует точное количество материалов на склад.</li><li>Пересчитывает средневзвешенную цену каждой позиции с учетом доставки (метод МАК).</li><li>Создает в журнале движения денег (ДДС) два прозрачных расходных ордера: <em>«Закупка сырья»</em> и <em>«Доставка сырья»</em>.</li></ol><hr><h2 id="маркировка-склада-и-автономная-печать-этикеток" tabindex="-1">Маркировка склада и автономная печать этикеток <a class="header-anchor" href="#маркировка-склада-и-автономная-печать-этикеток" aria-label="Permalink to &quot;Маркировка склада и автономная печать этикеток&quot;">​</a></h2><p>ОмниКрафт ЕРП оснащен встроенным генератором складских этикеток и штрихкодов, работающим полностью автономно без подключения к интернету и облачным сервисам.</p><p>Печать доступна как поштучно из карточки материала, так и массово для целого стеллажа через кнопку <strong>«Пакетная печать бирок»</strong>.</p><h3 id="режимы-кодирования-этикеток" tabindex="-1">Режимы кодирования этикеток <a class="header-anchor" href="#режимы-кодирования-этикеток" aria-label="Permalink to &quot;Режимы кодирования этикеток&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Режим</th><th style="text-align:left;">Тип кода</th><th style="text-align:left;">Практическое применение</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Артикул</strong></td><td style="text-align:left;">Линейный штрихкод Code128</td><td style="text-align:left;">Мгновенный поиск материала ручным сканером штрихкодов</td></tr><tr><td style="text-align:left;"><strong>Заказ у поставщика</strong></td><td style="text-align:left;">QR-код прямой ссылки</td><td style="text-align:left;">Наведение камеры смартфона на коробку сразу открывает сайт поставщика для дозаказа</td></tr><tr><td style="text-align:left;"><strong>Паспорт материала</strong></td><td style="text-align:left;">Текстовый QR-код</td><td style="text-align:left;">Считывание полных характеристик, остатка и условий хранения без включения компьютера</td></tr><tr><td style="text-align:left;"><strong>Комбинированный</strong></td><td style="text-align:left;">Штрихкод + QR-код</td><td style="text-align:left;">Оптимально для стандартных наклеек от 58×40 мм</td></tr><tr><td style="text-align:left;"><strong>Только текст</strong></td><td style="text-align:left;">Крупный шрифт без кодов</td><td style="text-align:left;">Для миниатюрных ячеек, пробирок и баночек (30×20 мм)</td></tr></tbody></table><h3 id="профессиональная-калибровка-принтера-смещение-x-y" tabindex="-1">Профессиональная калибровка принтера (смещение X / Y) <a class="header-anchor" href="#профессиональная-калибровка-принтера-смещение-x-y" aria-label="Permalink to &quot;Профессиональная калибровка принтера (смещение X / Y)&quot;">​</a></h3><p>Разные типы печатного оборудования имеют механические допуски: офисные лазерные принтеры на листах А4 со временем сдвигают подачу бумаги роликами, а рулонные термопринтеры имеют люфт по датчику зазора ленты.</p><p>В окне печати предусмотрен блок <strong>«Калибровка принтера (мм)»</strong>:</p><ul><li><strong>Сдвиг по вертикали (Y, мм):</strong> точная корректировка положения макета вверх или вниз (например, значение <code>-2.0</code> поднимает отпечаток ровно на 2 миллиметра).</li><li><strong>Сдвиг по горизонтали (X, мм):</strong> выравнивание печати строго по центру вырубки наклейки.</li><li><strong>Выбор окантовки:</strong> печать без рамки (для готовых самоклеящихся листов с насечкой), пунктирная рамка (для нарезки ножницами с обычного листа А4) или декоративная сплошная рамка для крафтовых бирок.</li></ul><p>Значения калибровки сохраняются в памяти программы один раз и применяются ко всем последующим тиражам автоматически.</p><hr><h2 id="инвентаризация-брак-и-корректировка-остатков" tabindex="-1">Инвентаризация, брак и корректировка остатков <a class="header-anchor" href="#инвентаризация-брак-и-корректировка-остатков" aria-label="Permalink to &quot;Инвентаризация, брак и корректировка остатков&quot;">​</a></h2><p>Помимо штатных закупок, на складе неизбежно происходят эксплуатационные события:</p><ol><li><strong>Плановая ревизия (Акт инвентаризации):</strong> при пересчете полок вы указываете фактическое количество в наличии. Программа фиксирует расхождение (излишек или недостачу), <strong>не изменяя при этом себестоимость единицы (МАК)</strong>.</li><li><strong>Списание брака и потерь (Акт списания):</strong> при обнаружении скрытого дефекта, повреждении сырья или естественной технологической убыли материал списывается с указанием причины. Балансовая стоимость списанного сырья корректно уменьшает складской капитал бизнеса.</li><li><strong>Журнал операций:</strong> любая операция (приход, бронь под заказ, списание на верстак, возврат, ручная правка) навсегда сохраняется в несмываемом хронологическом журнале с указанием даты и времени.</li></ol>',65))])}const k=r(h,[["render",p]]);export{q as __pageData,k as default};
